from pathlib import Path
import html,json,re
ROOT=Path(__file__).parent
LESSONS=[
('01','problem','何を商品にするか決める','知識より先に、誰の何を解決するのか','経験を棚卸しし、購入者の困りごとと結びつける。',[
('困りごとを先に決める','「自分が何を知っているか」だけでは商品は決まりません。買い手の状況、困りごと、解決後の状態の三つを具体的に置くところから始めます。経験や専門性は、その問題を解決できる理由になります。'),
('課題の粒度を下げる','「勉強に困っている」は範囲が広すぎます。いつ、何と比べて、何ができないのか。たとえば「資格試験の対策資料が見つからず、勉強の順番を決められない」のように、実際の行動が見える形まで狭めます。'),
('材料を探す場所','自分の現場で繰り返し説明してきたこと、読者の質問やレビュー、検索時に使われる言葉。これらは課題候補の手掛かりです。ただし、検索候補があるだけで購入需要があるとは断定できません。'),
('ここで作る成果物','「誰が・何に困り・何ができるようになるか」の一文と、それを支える本人の経験を一つ記録します。次のテーマでは、この成果物を教材や商品の目次に変えます。')],
['想定読者を「全員」にしない','経験のない実績を足さない','買い手の言葉と自分の思い込みを分ける']),
('02','design','知識を商品に組み立てる','教材やnoteの価値は、情報量ではなく到達できる順番','ゴールから逆算して目次・章・演習を設計する。',[
('目次を「できること」で作る','購入者が商品を使い終わったとき、何ができる状態になっているかを一文にします。そこから中間地点を分解し、前提関係の順番で並べていきます。'),
('知識を棚卸しする','既存記事、画像、記録、手順、よく受ける質問を一覧化します。「収録する内容」「重複している内容」「足りない内容」「入れない内容」を区別すると、制作量を過大に見積もらずに済みます。'),
('読んで終わりにしない','一章ごとに問題、チェック項目、実践課題のいずれかを置きます。「学んだ」ではなく「実行できた」を判断できる形式です。'),
('ここで作る成果物','商品の目次、各章でできるようになること、足りない素材の一覧を作ります。単品記事を束ねる場合も、「寄せ集め」ではなく目的までの道筋が必要です。')],
['目次と実際の中身を一致させる','先に100本の記事を作ろうとしない','既存の素材を無理に全て入れない']),
('03','offer','オファーと価格を決める','価格を決める前に、何をどんな条件で届けるか','中身・束ね方・条件を分けて商品の提示方法を設計する。',[
('オファーは商品名ではない','商品に何が含まれ、どこまで支援し、購入後に何を受け取れるのか。それらを買い手へ示す全体がオファーです。'),
('先に商品構成を確定する','単品かセットか、更新はあるか、対象外は誰か。こうした条件によって購入の判断材料が変わります。価格だけ先に決めると、理由が後付けになりやすくなります。'),
('比較材料を用意する','類似商品の価格、個別購入した場合の費用、セット固有の価値などを正確に比較します。根拠のない定価や実態のない期限表示は採用しません。'),
('ここで作る成果物','収録範囲、提供形態、対象・対象外、価格候補、比較に使った根拠と確認日を一つのシートにします。')],
['売上試算を実績として書かない','架空の割引前価格を表示しない','対象外の人も明示する']),
('04','sales','販売ページを設計する','買い手が判断できる情報を、必要な順番で提示する','販売ページを不安解消と購入判断の資料にする。',[
('読者が知りたい順番','困りごと、解決策、収録内容、根拠、向いていない人、よくある疑問、価格と購入方法。これは出発点となる構成例であり、すべての商品で順番を固定する必要はありません。'),
('「中身」を見せる','具体的な目次、教材サンプル、使用方法、更新条件があると、買い手は自分に必要かどうか判断できます。「充実しています」だけでは判断材料になりません。'),
('信用の根拠','本人が実際に経験したこと、公開可能な制作過程、確認できる数字を扱います。他人の成功事例を自分の成果のように見せたり、保証できない結果を約束したりしません。'),
('ここで作る成果物','販売ページの見出し、サンプル掲載位置、FAQ、価格・条件の掲載位置を一つの設計図にします。')],
['販売ページだけで中身を大きく見せない','誇張や「誰でも」を避ける','購入後の受け取り方法まで説明する']),
('05','reach','商品を知ってもらう','検索とSNSは、困りごとから商品へつながる通路','学習サイトの集客テーマ。原資料未添付のため公開本文は準備中。',[
('集客は商品設計の続き','商品の対象者と解決する課題が明確であれば、読者が探す記事テーマやSNS投稿の切り口を考えやすくなります。'),
('記事と販売ページの役割','無料記事は読者が困っていることに応える場所、販売ページは商品内容と条件を判断する場所です。必要なときに自然に移動できるようにします。'),
('計測してから改善する','検索結果の表示、記事の閲覧、販売ページへの遷移は別の段階です。ひとつの数字だけで売上への効果を判断しないようにします。'),
('このテーマの状態','テーマ5の詳細原稿はまだ提供されていません。上記は他のテーマとの接続を示す仮の概要です。正式な教材としての公開前に、独立した調査と執筆・確認が必要です。')],
['検索順位を保証しない','ユーザーの行動を推測値で埋めない','原稿確定前はインデックス対象にしない']),
('06','improve','売った後に改善する','数字は眺めるためでなく、次の修正箇所を決めるため','記事から販売までの流れを分けて振り返る。',[
('まず見る指標を決める','記事ごとの閲覧、反応、販売ページへの到達、販売の内訳、継続利用。確認できる範囲だけを記録し、取得できない数字は空欄にします。'),
('どこで止まったかを見る','記事が読まれない、記事は読まれるが販売ページへ進まない、販売ページまで来るが購入されない。位置によって疑うべき原因は違います。'),
('修正対象を一つに絞る','記録した数値と観察から一つ仮説を立て、次の確認日を決めます。複数を同時に変えると、改善の原因を判別しにくくなります。'),
('ここで作る成果物','変更前の数字、考えた仮説、実施した修正、次に見る指標を月次の実践記録にします。振り返りを次の商品や記事に再利用します。')],
['見られた数と買われた数を混同しない','測定できない数字は推測で補わない','数日間の変動だけで結論を出さない'])]

CSS='/assets/site.css?v=1'
JS='/assets/studio.js?v=1'

def header(active=''):
 return f'''<header class="site-header"><div class="nav-wrap"><a class="brand" href="/"><span class="brand-mark">k.</span><span>商材設計ラボ <small>Knowledge Product Studio</small></span></a><nav aria-label="メインナビ"><a class="{'active' if active=='learn' else ''}" href="/learn/">学ぶ</a><a class="{'active' if active=='studio' else ''}" href="/studio/">商品設計ボード</a><a href="/about/">このサイトについて</a></nav></div></header>'''

def layout(title, desc, body, active='',noindex=True, extra_script=''):
 metarobots='<meta name="robots" content="noindex,nofollow">' if noindex else ''
 return f'''<!doctype html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | 商材設計ラボ</title><meta name="description" content="{html.escape(desc)}">{metarobots}<meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><link rel="stylesheet" href="{CSS}"></head><body>{header(active)}{body}<footer class="footer"><div class="container footer-inner"><span>商材設計ラボ <span class="muted">— 商品の作り方を、考えるところから。</span></span><a href="/about/">運営・データについて</a><span class="muted">© 2026 Knowledge Product Studio / 仮称</span></div></footer>{extra_script}</body></html>'''

def card(n,slug,title,desc):
 return f'<a class="lesson-card" href="/learn/{slug}/"><span class="chapter">LESSON {n}</span><span class="lesson-title">{html.escape(title)}</span><span class="lesson-desc">{html.escape(desc)}</span><span class="lesson-next">記事を読む <span aria-hidden="true">↗</span></span></a>'

home='''<main><div class="hero container"><div><span class="eyebrow"><span class="status-dot"></span> 知識を、売れる形へ近づけるために</span><h1>何を商品にして、<br><em>どう売ればいいか。</em><br>その答えを、自分で作る。</h1><p class="lead">経験や知識はある。でも、何を誰に届ければ商品になるのかわからない。商材設計ラボは、電子商材を考えるための学習記事と、自分の企画を整理できるワークスペースをつなぐ場所です。</p><div class="hero-actions"><a class="button primary" href="/studio/">商品アイデアを整理する <span>→</span></a><a class="button secondary" href="/learn/">6つのテーマから学ぶ</a></div><div class="hero-foot">note / PDF / 教材 / デジタルツールなどの企画に対応 · 無料の初期版</div></div><div class="hero-illustration"><div class="sketch-head"><span>PRODUCT MAP</span><span>01 — 04</span></div><div class="sketch-center">あなたの<br><b>知識・経験</b></div><div class="sketch-branch">誰の悩み？ <span>→</span></div><div class="sketch-branch b2">何が変わる？ <span>→</span></div><div class="sketch-branch b3">どんな商品？ <span>→</span></div><div class="sketch-bottom">アイデア → 設計 → 販売 → 改善</div></div></div><section class="container section"><div class="section-heading"><div><div class="eyebrow">LEARNING ROADMAP</div><h2>作り方を、順序立てて学ぶ。</h2><p>一つずつ理解し、設計ボードに書き戻す。知識だけで終わらない構成です。</p></div><a class="simple-link" href="/learn/">学習テーマ一覧を見る ↗</a></div><div class="lesson-grid">'''+''.join(card(n,slug,title,desc) for n,slug,title,sub,desc,body,checks in LESSONS)+'''</div></section><section class="muted-section"><div class="container split"><div><div class="eyebrow">BUILD YOUR PRODUCT</div><h2>考えたことを、<br>そのまま設計に残す。</h2><p>記事で学んだ「誰に、何を、どんな形で届けるか」をボードに保存。企画の要点を編集しながら、最後にJSONで持ち出せます。</p><a class="button dark" href="/studio/">設計ボードを開く →</a></div><div class="feature-stack"><div class="feature"><strong>01</strong><div><b>課題と相手を整理</b><span>経験の棚卸しを商品アイデアに変える</span></div></div><div class="feature"><strong>02</strong><div><b>目次と価格を設計</b><span>中身と条件を決め、無理のない提供形態を選ぶ</span></div></div><div class="feature"><strong>03</strong><div><b>検証を続ける</b><span>売上の予測と実績を混同せず、改善を記録する</span></div></div></div></div></section><section class="container section small-cta"><div><div class="eyebrow">OUR APPROACH</div><h2>売れると断定しない。<br>買う理由を、説明できるようにする。</h2><p>初期版は文章生成AIや自動販売ではなく、商品設計の土台づくりを支援します。サイト運営側の制作・SEO分析はGitHubなどで管理し、利用者には複雑な開発操作を求めません。</p></div></section></main>'''
(ROOT/'index.html').write_text(layout('自分の知識を電子商材にする学習と設計の場所','有料note、PDF教材、デジタル商品を作りたい人へ。何を誰に売るかを学習し、商品アイデアを視覚的に整理できる初期版サービス。',home),encoding='utf-8')

learning='''<main class="container page-main"><div class="eyebrow">LEARN</div><h1>電子商材の作り方を学ぶ</h1><p class="lead narrow">何を商品にするかから、構成、価格、販売、改善まで。読むだけで終わらず、各テーマで決めたことを設計ボードへつなぎます。</p><div class="notice">現在は公開前の確認版です。教材は編集確認中で、テーマ5の原稿は準備中です。</div><div class="lesson-grid roomy">'''+''.join(card(n,slug,title,desc) for n,slug,title,sub,desc,body,checks in LESSONS)+'''</div><div class="bottom-panel"><h2>読みながら、あなたの商品の設計も進める</h2><p>入力した内容は現在の端末のブラウザに保存されます。アカウント登録やサーバーへの送信は行いません。</p><a class="button primary" href="/studio/">商品設計ボードへ →</a></div></main>'''
(ROOT/'learn'/'index.html').write_text(layout('電子商材の作り方・学習テーマ一覧','有料noteやPDF教材などの電子商材を企画・販売するまでを6つのテーマで整理。',learning,active='learn'),encoding='utf-8')

for idx,(n,slug,title,sub,desc,topics,checks) in enumerate(LESSONS):
  siblings=''.join(f'<a class="side-item {"selected" if slug==s else ""}" href="/learn/{s}/"><span>{n2}</span>{html.escape(t)}</a>' for n2,s,t,_,_,_,_ in LESSONS)
  sections=''.join(f'<section id="part-{i+1}" class="article-section"><h2>{html.escape(t)}</h2><p>{html.escape(txt)}</p></section>' for i,(t,txt) in enumerate(topics))
  checklist=''.join(f'<li>{html.escape(c)}</li>' for c in checks)
  nxt=LESSONS[idx+1] if idx+1<len(LESSONS) else None
  nextlink=f'<a class="next-lesson" href="/learn/{nxt[1]}/"><span>次のテーマ</span><strong>{html.escape(nxt[2])} →</strong></a>' if nxt else '<a class="next-lesson" href="/learn/"><span>学習を終えたら</span><strong>もう一度、自分の商品の課題を見直す →</strong></a>'
  notice='<div class="notice">この記事は編集確認中の教材プレビューです。公開前に最新情報と表現を点検します。</div>'
  if slug=='reach':notice='<div class="notice warn">テーマ5の原稿は未添付のため、こちらは構成確認用の仮ページです。正式な記事は未完成です。</div>'
  body=f'''<main class="container article-layout"><article class="article"><div class="bread"><a href="/">ホーム</a> / <a href="/learn/">学ぶ</a> / テーマ{n}</div><div class="eyebrow">LESSON {n} / PRODUCT DESIGN</div><h1>{html.escape(title)}</h1><p class="article-lead">{html.escape(sub)}。</p>{notice}<div class="article-summary"><b>このテーマの到達点</b><p>{html.escape(desc)}</p></div>{sections}<section class="article-section check-panel"><h2>制作時の確認ポイント</h2><ul>{checklist}</ul></section><section class="work-callout"><div class="eyebrow">APPLY WHAT YOU LEARN</div><h2>自分の商品で考えてみる</h2><p>読んだ内容を商品設計ボードの該当項目へ書き込みます。次のテーマでも同じ企画を引き継げます。</p><a class="button primary" href="/studio/?lesson={slug}">商品設計ボードを開く →</a></section>{nextlink}</article><aside class="article-sidebar"><div class="side-title">学習の目次</div>{siblings}<div class="side-note">作業中の企画は商品設計ボードへ。ページを移動しても入力内容は同じ端末に保存されます。</div><a class="button secondary small" href="/studio/">商品設計ボード ↗</a></aside></main>'''
  target=ROOT/'learn'/slug;target.mkdir(exist_ok=True)
  (target/'index.html').write_text(layout(f'{title}｜電子商材の作り方',f'{desc} 電子商材や有料noteの作り方を学ぶテーマ{n}。',body,active='learn'),encoding='utf-8')

studio='''<main class="container studio-main"><div class="bread"><a href="/">ホーム</a> / 商品設計ボード</div><div class="studio-heading"><div><div class="eyebrow">YOUR PRODUCT WORKSPACE</div><h1>商品設計ボード</h1><p>自分の知識と買い手の困りごとをつなぎ、一つの電子商材の設計を進めます。</p></div><div class="studio-actions"><span id="saveStatus" class="save-status" role="status" aria-live="polite">この端末に保存</span><button id="exportBtn" class="button secondary" type="button">JSONを書き出す</button><label for="importInput" class="button secondary file-label">JSONを読み込む</label><input id="importInput" type="file" accept="application/json,.json" hidden></div></div><div class="notice storage-note">この試作版では入力データはこのブラウザ内のみ（localStorage）に保存されます。別端末との同期、会員登録、バックアップはありません。消去に備え、JSONを書き出して保管してください。</div><div class="studio-tabs" role="tablist" aria-label="設計画面の切り替え"><button class="tab active" data-panel="map" role="tab" aria-selected="true">商品マップ</button><button class="tab" data-panel="sheet" role="tab" aria-selected="false">商品設計シート</button><button class="tab" data-panel="review" role="tab" aria-selected="false">完成チェック</button></div><section id="panel-map" class="panel active"><div class="map-intro"><div><h2>商品アイデアの関係図</h2><p>下のカードを編集すると、このマップにも反映されます。まずは誰のどんな困りごとを扱うか考えます。</p></div><button class="simple-btn" type="button" id="resetSample">入力例に戻す</button></div><div class="product-map" id="productMap"><div class="map-layer"><div class="map-node top" id="node-experience"><span>持っている経験</span><strong data-field="experience"></strong></div><div class="map-node left" id="node-audience"><span>届けたい相手</span><strong data-field="audience"></strong></div><div class="map-node middle main-node" id="node-product"><span>作りたい商品</span><strong data-field="productName"></strong></div><div class="map-node right" id="node-problem"><span>相手の困りごと</span><strong data-field="problem"></strong></div><div class="map-node bottom" id="node-outcome"><span>購入後の変化</span><strong data-field="outcome"></strong></div></div></div><div class="quick-edit"><h3>まず、この5つを書き換える</h3><div class="field-grid"><label>自分の経験・知識<textarea name="experience" rows="2"></textarea></label><label>想定する読者・買い手<textarea name="audience" rows="2"></textarea></label><label>相手の困りごと<textarea name="problem" rows="2"></textarea></label><label>解決後にできること<textarea name="outcome" rows="2"></textarea></label><label class="wide">仮の商品名<input name="productName" type="text"></label></div></div></section><section id="panel-sheet" class="panel" hidden><div class="panel-head"><h2>商品設計シート</h2><p>各テーマで考えた内容を一枚にまとめます。途中でも保存できます。</p></div><div class="field-grid sheet-fields"><label>商品形式<select name="format"><option value="note記事">note有料記事</option><option value="PDF教材">PDF教材</option><option value="有料マガジン">有料マガジン</option><option value="Webアプリ">Webアプリ</option><option value="オンライン講座">オンライン講座</option><option value="その他">その他</option></select></label><label>価格案（円）<input type="number" name="price" min="0" step="1" placeholder="未定なら空欄"></label><label class="wide">販売する内容・目次<textarea name="outline" rows="5" placeholder="例：第1章… / 第2章…"></textarea></label><label class="wide">他の方法と比べた価値・根拠<textarea name="value" rows="3"></textarea></label><label class="wide">向いていない人・含まない内容<textarea name="exclusions" rows="3"></textarea></label><label class="wide">販売ページで証明できる材料<textarea name="evidence" rows="3" placeholder="目次、サンプル、制作経緯、確認できる実績"></textarea></label><label class="wide">販売先や届け方<textarea name="channel" rows="2" placeholder="例：note / ダウンロードリンク / その他"></textarea></label></div></section><section id="panel-review" class="panel" hidden><div class="panel-head"><h2>商品として説明できるか</h2><p>AIによる需要予測ではなく、入力済み項目と設計上の確認です。販売や売上を保証するものではありません。</p></div><div id="reviewList" class="review-list"></div><div class="review-hint">空欄や未確認を整理した後、商品の本文・目次・サンプルを制作してください。現時点で外部サービスへの自動投稿は行いません。</div></section><div class="studio-bottom"><a href="/learn/">← 6テーマの教材へ戻る</a><button id="clearBtn" class="text-danger" type="button">この端末の入力を初期化</button></div></main>'''
(ROOT/'studio'/'index.html').write_text(layout('商品設計ボード｜電子商材の企画を整理する','経験・課題・商品構成・価格・販売条件を一か所に整理。電子商材の企画を端末内に保存・JSON出力できます。',studio,active='studio',extra_script=f'<script defer src="{JS}"></script>'),encoding='utf-8')
about='''<main class="container page-main prose"><div class="eyebrow">ABOUT</div><h1>このサイトについて</h1><p>商材設計ラボ（仮称）は、自分の経験や専門知識を有料note、PDF、教材、デジタルツールなどへ変換したい人のための学習・設計サイトです。特定の商品が売れることや収益を保証するものではありません。</p><h2>教材について</h2><p>個人の教材制作、note運営、Webアプリ開発の経験と、商品設計に関する調査をもとに構成しています。教材は現在レビュー前のプレビューです。テーマ5は原稿未提供のため仮の概要のみ掲載しています。外部サイトや他人の成果を本人の実績として表示しません。</p><h2>保存・プライバシーについて</h2><p>初期版の設計ボードはブラウザのlocalStorageへ保存します。入力情報をサーバーに送信するプログラム、アクセスログイン、第三者への販売は実装していません。ブラウザのデータ消去や端末変更で失われる可能性があります。JSONエクスポートで手元に控えを残してください。端末内保存のため複数端末からの同期はできません。</p><h2>サービスの状態</h2><p>本版は公開前の試作版です。決済、会員登録、外部AIによる記事自動生成、noteの自動投稿、Museとの連携はありません。内容・デザイン・価格体系は正式公開前に見直します。</p><a class="button secondary" href="/">ホームに戻る →</a></main>'''
(ROOT/'about').mkdir(exist_ok=True)
(ROOT/'about'/'index.html').write_text(layout('運営とデータ保存について','商材設計ラボの目的、教材の状態、商品設計ボードの保存・プライバシー方針を案内します。',about),encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nDisallow: /\n',encoding='utf-8')
(ROOT/'vercel.json').write_text(json.dumps({'cleanUrls':True,'trailingSlash':True,'headers':[{'source':'/(.*)','headers':[{'key':'X-Robots-Tag','value':'noindex, nofollow'},{'key':'X-Content-Type-Options','value':'nosniff'},{'key':'Referrer-Policy','value':'strict-origin-when-cross-origin'}]}]},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'README.md').write_text('''# 商材設計ラボ / Knowledge Product Studio (仮称)\n\n電子商材の作り方を学びながら、自分の商品企画を形にするWebサイトの初期版です。\n\n## 現状\n\n- 学ぶ：テーマ1,2,3,4,6の教材プレビュー、テーマ5の構成仮ページ\n- 作る：商品マップ、商品設計シート、完成チェック\n- 保存：localStorage、JSONエクスポート・インポート（ユーザーデータはサーバー非送信）\n- SEO：静的記事別URL、固有title/description、内部リンクを実装。ただし公開前レビューのため全ページnoindex\n- 未実装：ユーザー認証、同期、決済、Muse連携、note投稿、Analytics/SC連携\n\n## 手元で起動\n\n`python3 -m http.server 8000` をこのディレクトリで実行して `http://localhost:8000` へアクセス。静的ファイルのみで動作します。\n\n## 記事の出典と編集状態\n\n2026-11-01に提供された学習ハブのテーマ1,2,3,4,6のMarkdown原稿を資料に、新サイト向けに要点を再構成。原稿は本人による公開前レビュー前提。テーマ5は原稿未提供なので仮の概要だけ。\n\n## 運営構成\n\n- COS（既存の private repo）：運営者Brain、Knowledge、監査、記事企画の正本。**内容を直接公開しない**。\n- 本リポジトリ：公開予定の教材と利用者向けアプリのソース。\n- Vercel：静的ホスティング予定。\n- 将来のユーザーデータ保管：独立したDB/認証基盤へ。GitHub commitをユーザー操作の保存先にしない。\n\n## 公開前チェック\n\n1. ブランド名・サイトURL・運営者連絡先・プライバシーポリシーを確定\n2. テーマ5の正式原稿を作成し、テーマ1〜6を全て編集確認\n3. 公開前にnoindexを解除してsitemap.xml、canonical、OG画像を追加\n4. 記事・スマホUI・保存/復元・各リンクを実機点検\n5. 本番公開後にGoogle Search Consoleなどを接続\n''',encoding='utf-8')
print('Generated pages:',len(list(ROOT.rglob('*.html'))))
